def ensure_project_files(project_root=None):
    """التأكد من وجود وتحديث جميع ملفات القوالب (templates) والملفات الثابتة (static) على القرص المحلي."""
    root = project_root or PROJECT_ROOT
    tpl_dir = os.path.join(root, "templates")
    stc_dir = os.path.join(root, "static")
    os.makedirs(tpl_dir, exist_ok=True)
    os.makedirs(stc_dir, exist_ok=True)

    for filename, content in DEFAULT_TEMPLATES.items():
        fpath = os.path.join(tpl_dir, filename)
        need_write = not os.path.exists(fpath) or os.path.getsize(fpath) == 0
        if not need_write:
            try:
                with open(fpath, "r", encoding="utf-8") as rf:
                    if VERSION_MARKER not in rf.read():
                        need_write = True
            except Exception:
                need_write = True
        if need_write:
            with open(fpath, "w", encoding="utf-8") as wf:
                wf.write(content)

    for filename, content in DEFAULT_STATIC.items():
        fpath = os.path.join(stc_dir, filename)
        need_write = not os.path.exists(fpath) or os.path.getsize(fpath) == 0
        if not need_write:
            try:
                with open(fpath, "r", encoding="utf-8") as rf:
                    if VERSION_MARKER not in rf.read():
                        need_write = True
            except Exception:
                need_write = True
        if need_write:
            with open(fpath, "w", encoding="utf-8") as wf:
                wf.write(content)


def hash_password(password):
    """تشفير كلمة المرور باستخدام خوارزمية SHA-256."""
    return hashlib.sha256(password.encode("utf-8")).hexdigest()


def get_connection():
    """إنشاء اتصال بقاعدة البيانات مع إرجاع الصفوف كـ Dictionary."""
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    """إنشاء الجداول، ترقية قاعدة البيانات القديمة تلقائياً، وإضافة الحساب الافتراضي والبيانات الأولية."""
    ensure_project_files()
    conn = get_connection()
    cursor = conn.cursor()

    conn.executescript("""
    CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT NOT NULL UNIQUE,
        display_name TEXT NOT NULL,
        password_hash TEXT NOT NULL,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
    CREATE TABLE IF NOT EXISTS tasks (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER DEFAULT 1,
        title TEXT NOT NULL,
        category TEXT DEFAULT 'study',
        priority TEXT DEFAULT 'medium',
        due_date TEXT DEFAULT '',
        due_time TEXT DEFAULT '',
        completed INTEGER DEFAULT 0,
        notes TEXT DEFAULT '',
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
    CREATE TABLE IF NOT EXISTS habits (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER DEFAULT 1,
        name TEXT NOT NULL,
        icon TEXT DEFAULT '🔥',
        target_days INTEGER DEFAULT 7,
        streak INTEGER DEFAULT 0,
        completed_today INTEGER DEFAULT 0,
        last_completed_date TEXT DEFAULT '',
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
    CREATE TABLE IF NOT EXISTS transactions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER DEFAULT 1,
        title TEXT NOT NULL,
        amount REAL NOT NULL,
        tx_type TEXT NOT NULL,
        category TEXT DEFAULT 'general',
        tx_date TEXT DEFAULT '',
        notes TEXT DEFAULT '',
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
    CREATE TABLE IF NOT EXISTS settings (
        key TEXT PRIMARY KEY,
        value TEXT NOT NULL
    );
    """)

    # ترقية الجداول السابقة إذا كانت لا تحتوي على عمود user_id
    for tbl in ("tasks", "habits", "transactions"):
        try:
            cursor.execute(f"ALTER TABLE {tbl} ADD COLUMN user_id INTEGER DEFAULT 1")
        except sqlite3.OperationalError:
            pass

    today_str = date.today().isoformat()

    # 1. إنشاء الحساب الافتراضي (admin / 1234) إذا لم يكن هناك مستخدمون
    cursor.execute("SELECT COUNT(*) as cnt FROM users")
    if cursor.fetchone()["cnt"] == 0:
        cursor.execute(
            "INSERT INTO users (username, display_name, password_hash) VALUES (?, ?, ?)",
            ("admin", "سهل | Sahl", hash_password("1234")),
        )

    # 2. إضافة مهام افتراضية إذا كان جدول المهام فارغاً
    cursor.execute("SELECT COUNT(*) as cnt FROM tasks")
    if cursor.fetchone()["cnt"] == 0:
        sample_tasks = [
            (1, "مراجعة المحاضرات الدراسية", "study", "high", today_str, "09:00", 0, "مراجعة محاضرة الرياضيات والفيزياء"),
            (1, "جلسة برمجة لمدة ساعة", "coding", "high", today_str, "14:00", 0, "تطوير مشروع إدارة حياتي بـ Flask"),
            (1, "تمارين رياضية خفيفة", "sport", "medium", today_str, "18:00", 1, "تمارين إطالة ومشي 30 دقيقة"),
            (1, "قراءة فصل من كتاب تقني", "personal", "low", today_str, "21:00", 0, "فصل 3 من كتاب Clean Code"),
        ]
        cursor.executemany(
            "INSERT INTO tasks (user_id, title, category, priority, due_date, due_time, completed, notes) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            sample_tasks,
        )

    # 3. إضافة عادات افتراضية إذا كان جدول العادات فارغاً
    cursor.execute("SELECT COUNT(*) as cnt FROM habits")
    if cursor.fetchone()["cnt"] == 0:
        sample_habits = [
            (1, "شرب الماء (8 أكواب)", "💧", 7, 5, 1, today_str),
            (1, "القراءة اليومية (20 صفحة)", "📚", 7, 3, 1, today_str),
            (1, "تمارين رياضية", "🏋️", 5, 0, 0, ""),
            (1, "مراجعة البرمجة (ساعة)", "💻", 6, 4, 1, today_str),
        ]
        cursor.executemany(
            "INSERT INTO habits (user_id, name, icon, target_days, streak, completed_today, last_completed_date) VALUES (?, ?, ?, ?, ?, ?, ?)",
            sample_habits,
        )

    # 4. إضافة معاملات مالية افتراضية إذا كان جدول الماليات فارغاً
    cursor.execute("SELECT COUNT(*) as cnt FROM transactions")
    if cursor.fetchone()["cnt"] == 0:
        sample_tx = [
            (1, "راتب / منحة شهرية", 1560.50, "income", "salary", today_str, "إيداع بداية الشهر"),
            (1, "شراء كتب ومراجع دراسية", 120.00, "expense", "study", today_str, "كتب هندسة وبرمجة"),
            (1, "مصاريف طعام وقهوة", 115.50, "expense", "food", today_str, "مصاريف الأسبوع"),
            (1, "اشتراك إنترنت ومواصلات", 85.00, "expense", "transport", today_str, "باقة الشهر"),
        ]
        cursor.executemany(
            "INSERT INTO transactions (user_id, title, amount, tx_type, category, tx_date, notes) VALUES (?, ?, ?, ?, ?, ?, ?)",
            sample_tx,
        )

    cursor.execute("INSERT OR IGNORE INTO settings (key, value) VALUES ('monthly_budget', '800.00')")

    conn.commit()
    conn.close()


