def authenticate_user(username, password):
    """التحقق من اسم المستخدم وكلمة المرور وإرجاع بيانات المستخدم إذا كانت صحيحة."""
    if not username or not password:
        return None
    conn = get_connection()
    row = conn.execute(
        "SELECT id, username, display_name, password_hash FROM users WHERE LOWER(username) = LOWER(?)",
        (username.strip(),),
    ).fetchone()
    conn.close()
    if row and row["password_hash"] == hash_password(password):
        return {"id": row["id"], "username": row["username"], "display_name": row["display_name"]}
    return None


def create_user(username, display_name, password):
    """إنشاء حساب مستخدم جديد مع تهيئة بيانات أولية له."""
    uname = (username or "").strip()
    dname = (display_name or uname).strip()
    if not uname or not password:
        return None, "يرجى إدخال اسم المستخدم وكلمة المرور / Please enter username and password."
    if len(password) < 3:
        return None, "كلمة المرور قصيرة جداً / Password is too short."

    conn = get_connection()
    existing = conn.execute(
        "SELECT id FROM users WHERE LOWER(username) = LOWER(?)", (uname,)
    ).fetchone()
    if existing:
        conn.close()
        return None, "اسم المستخدم مسجل بالفعل، اختر اسماً آخر / Username already exists."

    cursor = conn.cursor()
    cursor.execute(
        "INSERT INTO users (username, display_name, password_hash) VALUES (?, ?, ?)",
        (uname, dname, hash_password(password)),
    )
    new_user_id = cursor.lastrowid
    # يبدأ المستخدم الجديد بقاعدة بيانات فارغة تماماً (بدون مهام أو عادات أو معاملات افتراضية)
    conn.commit()
    conn.close()
    return {"id": new_user_id, "username": uname, "display_name": dname}, None


def get_user_by_id(user_id):
    """جلب بيانات المستخدم بواسطة المعرف."""
    conn = get_connection()
    row = conn.execute(
        "SELECT id, username, display_name FROM users WHERE id = ?", (user_id,)
    ).fetchone()
    conn.close()
    return dict(row) if row else None


