def get_all_tasks(category=None, status=None, user_id=1):
    """جلب جميع المهام الخاصة بالمستخدم مع إمكانية التصفية."""
    conn = get_connection()
    query = "SELECT * FROM tasks WHERE COALESCE(user_id, 1) = ?"
    params = [user_id]

    if category and category != "all":
        query += " AND category = ?"
        params.append(category)

    if status == "pending":
        query += " AND completed = 0"
    elif status == "completed":
        query += " AND completed = 1"

    query += " ORDER BY completed ASC, due_date ASC, due_time ASC, id DESC"
    rows = conn.execute(query, params).fetchall()
    conn.close()
    return [dict(r) for r in rows]


def add_task(title, category="study", priority="medium", due_date="", due_time="", notes="", user_id=1):
    """إضافة مهمة جديدة إلى قاعدة البيانات."""
    if not due_date:
        due_date = date.today().isoformat()
    conn = get_connection()
    conn.execute(
        "INSERT INTO tasks (user_id, title, category, priority, due_date, due_time, completed, notes) VALUES (?, ?, ?, ?, ?, ?, 0, ?)",
        (user_id, title.strip(), category, priority, due_date, due_time, notes.strip()),
    )
    conn.commit()
    conn.close()


def toggle_task(task_id):
    """تغيير حالة المهمة (مكتملة <-> غير مكتملة)."""
    conn = get_connection()
    row = conn.execute("SELECT completed FROM tasks WHERE id = ?", (task_id,)).fetchone()
    new_state = 0
    if row is not None:
        new_state = 0 if row["completed"] else 1
        conn.execute("UPDATE tasks SET completed = ? WHERE id = ?", (new_state, task_id))
        conn.commit()
    conn.close()
    return new_state


def delete_task(task_id):
    """حذف مهمة من قاعدة البيانات."""
    conn = get_connection()
    conn.execute("DELETE FROM tasks WHERE id = ?", (task_id,))
    conn.commit()
    conn.close()


