def get_all_transactions(tx_type=None, user_id=1):
    """جلب جميع المعاملات المالية الخاصة بالمستخدم."""
    conn = get_connection()
    query = "SELECT * FROM transactions WHERE COALESCE(user_id, 1) = ?"
    params = [user_id]
    if tx_type in ("income", "expense"):
        query += " AND tx_type = ?"
        params.append(tx_type)
    query += " ORDER BY tx_date DESC, id DESC"
    rows = conn.execute(query, params).fetchall()
    conn.close()
    return [dict(r) for r in rows]


def get_finance_summary(user_id=1):
    """حساب ملخص الماليات للمستخدم."""
    conn = get_connection()
    income_row = conn.execute(
        "SELECT COALESCE(SUM(amount), 0) as total FROM transactions WHERE COALESCE(user_id, 1) = ? AND tx_type = 'income'",
        (user_id,),
    ).fetchone()
    expense_row = conn.execute(
        "SELECT COALESCE(SUM(amount), 0) as total FROM transactions WHERE COALESCE(user_id, 1) = ? AND tx_type = 'expense'",
        (user_id,),
    ).fetchone()
    budget_key = f"monthly_budget_{user_id}"
    budget_row = conn.execute(
        "SELECT value FROM settings WHERE key = ?",
        (budget_key,),
    ).fetchone()

    cat_rows = conn.execute(
        """
        SELECT category, SUM(amount) as total
        FROM transactions
        WHERE COALESCE(user_id, 1) = ? AND tx_type = 'expense'
        GROUP BY category
        ORDER BY total DESC
        """,
        (user_id,),
    ).fetchall()
    conn.close()

    total_income = float(income_row["total"]) if income_row else 0.0
    total_expense = float(expense_row["total"]) if expense_row else 0.0
    balance = total_income - total_expense
    monthly_budget = float(budget_row["value"]) if budget_row else (800.0 if user_id == 1 else 0.0)
    budget_percent = min(100, round((total_expense / monthly_budget) * 100, 1)) if monthly_budget > 0 else 0.0

    return {
        "total_income": total_income,
        "total_expense": total_expense,
        "balance": balance,
        "monthly_budget": monthly_budget,
        "budget_percent": budget_percent,
        "expenses_by_category": [dict(r) for r in cat_rows],
    }


def add_transaction(title, amount, tx_type="expense", category="general", tx_date="", notes="", user_id=1):
    """إضافة معاملة مالية جديدة."""
    if not tx_date:
        tx_date = date.today().isoformat()
    conn = get_connection()
    conn.execute(
        "INSERT INTO transactions (user_id, title, amount, tx_type, category, tx_date, notes) VALUES (?, ?, ?, ?, ?, ?, ?)",
        (user_id, title.strip(), float(amount), tx_type, category, tx_date, notes.strip()),
    )
    conn.commit()
    conn.close()


def update_monthly_budget(new_budget, user_id=1):
    """تحديث قيمة الميزانية الشهرية."""
    conn = get_connection()
    conn.execute(
        "INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)",
        (f"monthly_budget_{user_id}", str(float(new_budget))),
    )
    conn.execute(
        "INSERT OR REPLACE INTO settings (key, value) VALUES ('monthly_budget', ?)",
        (str(float(new_budget)),),
    )
    conn.commit()
    conn.close()


def delete_transaction(tx_id):
    """حذف معاملة مالية."""
    conn = get_connection()
    conn.execute("DELETE FROM transactions WHERE id = ?", (tx_id,))
